"""Lightweight frontend regression guards for template/script logic."""

import json
from pathlib import Path
import re
import shutil
import subprocess
import sys
import types
import unittest


ROOT = Path(__file__).resolve().parents[1]
LIGHT_SCHEME_SELECTOR = ':is([data-theme="light"], [data-theme="outlook"], [data-theme="teams"], [data-theme="custom"][data-custom-theme-scheme="light"])'

if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

if 'zeroconf' not in sys.modules:
    zeroconf_stub = types.ModuleType('zeroconf')

    class _DummyZeroconf:
        def __init__(self, *args, **kwargs):
            pass

    zeroconf_stub.ServiceBrowser = _DummyZeroconf
    zeroconf_stub.ServiceInfo = _DummyZeroconf
    zeroconf_stub.Zeroconf = _DummyZeroconf
    zeroconf_stub.ServiceStateChange = _DummyZeroconf
    sys.modules['zeroconf'] = zeroconf_stub


def read_feed_surface() -> str:
    templates_dir = ROOT / 'canopy' / 'ui' / 'templates'
    return (
        (templates_dir / 'feed.html').read_text(encoding='utf-8')
        + '\n'
        + (templates_dir / '_feed_posts_fragment.html').read_text(encoding='utf-8')
    )


class TestFrontendRegressions(unittest.TestCase):
    def test_canopy_llm_compose_ui_is_wired_to_channel_composer_and_profile(self) -> None:
        channels_template = (ROOT / 'canopy' / 'ui' / 'templates' / 'channels.html').read_text(encoding='utf-8')
        messages_template = (ROOT / 'canopy' / 'ui' / 'templates' / 'messages.html').read_text(encoding='utf-8')
        messages_composer = (ROOT / 'canopy' / 'ui' / 'templates' / '_messages_composer.html').read_text(encoding='utf-8')
        feed_template = read_feed_surface()
        profile_template = (ROOT / 'canopy' / 'ui' / 'templates' / 'profile.html').read_text(encoding='utf-8')
        main_js = (ROOT / 'canopy' / 'ui' / 'static' / 'js' / 'canopy-main.js').read_text(encoding='utf-8')

        self.assertIn('channel-canopy-llm-status', channels_template)
        self.assertIn('function hasCanopyLLMTrigger', channels_template)
        self.assertIn('function shouldGenerateCanopyLLMDraft', channels_template)
        self.assertIn('function isCanopyLLMTriggerIgnored', channels_template)
        self.assertIn('async function maybeExpandCanopyLLMDraft', channels_template)
        self.assertIn('async function generateCanopyLLMDraftFromComposer(event)', channels_template)
        self.assertIn('function updateCanopyLLMComposePanel()', channels_template)
        self.assertIn('let channelCanopyLLMIgnoredDraft = \'\';', channels_template)
        self.assertIn('id="channel-canopy-llm-generate"', channels_template)
        self.assertIn('id="channel-canopy-llm-dismiss"', channels_template)
        self.assertIn('Send as written', channels_template)
        self.assertIn('Ignore @Canopy for this exact draft and enable normal send', channels_template)
        self.assertIn('Draft inserted. Edit it, send when ready, or add @Canopy with instructions to refine again.', channels_template)
        self.assertIn('Canopy draft inserted. Review and send when ready.', channels_template)
        self.assertIn('const requestedCanopyLLM = shouldGenerateCanopyLLMDraft(effectiveRawContent);', channels_template)
        self.assertIn("sendBtn.setAttribute('title', 'Generate @Canopy draft for review');", channels_template)
        self.assertNotIn('Draft ready from ${modelLabel}; sending...', channels_template)
        self.assertIn('/ajax/canopy_llm/expand', channels_template)
        self.assertIn('async function sendMessage(event)', channels_template)
        self.assertIn('canopy-llm-compose-section', profile_template)
        self.assertIn('canopy-llm-api-key', profile_template)
        self.assertIn('canopy-llm-web-search-enabled', profile_template)
        self.assertIn('canopy-llm-memory-enabled', profile_template)
        self.assertIn('canopy-llm-compose-memory', profile_template)
        self.assertIn('Compose memory', profile_template)
        self.assertIn('gpt-5.4-mini', profile_template)
        self.assertIn('AWS Bedrock', profile_template)
        self.assertIn('canopy-llm-api-key-label', profile_template)
        self.assertIn('applyProviderCopy', profile_template)
        self.assertIn('aws_bearer_token_bedrock', profile_template)
        self.assertIn('anthropic.claude-3-5-sonnet', profile_template)
        self.assertIn('Allow hosted web search for current facts', profile_template)
        self.assertIn('memory_enabled: !!(memoryEnabledInput && memoryEnabledInput.checked)', profile_template)
        self.assertIn('compose_memory: composeMemoryInput ? composeMemoryInput.value.trim() : \'\'', profile_template)
        self.assertIn('/ajax/canopy_llm/settings', profile_template)
        self.assertIn('instance_fallback_available', profile_template)
        self.assertIn('admin-managed instance fallback', profile_template)
        self.assertIn('put the result back into the composer for review before you send', profile_template)
        self.assertIn('id="channel-composer-clear-btn"', channels_template)
        self.assertIn('function clearChannelComposerContent()', channels_template)
        self.assertIn('id="feed-composer-clear-btn"', feed_template)
        self.assertIn('function clearFeedComposerContent()', feed_template)
        self.assertIn('clearDmComposerDraft();', messages_template)
        self.assertIn('data-dm-role="canopy-llm-status"', messages_composer)
        self.assertIn('data-dm-action="generate-canopy-draft"', messages_composer)
        self.assertIn('async function generateDmCanopyLLMDraft', messages_template)
        self.assertIn('if (dmShouldGenerateCanopyLLMDraft(content))', messages_template)
        self.assertIn("surface: 'dm'", messages_template)
        self.assertIn('global.CanopyLLMCompose = {', main_js)
        self.assertIn('async function generateDeckInboxCanopyLLMDraft', main_js)
        self.assertIn('if (deckInboxShouldGenerateCanopyLLMDraft(content))', main_js)

